-- Optional DATABASE LINK fixture template.
-- Do not commit real remote credentials. Define values in the SQL*Plus session.
-- Example:
--   DEFINE ORACODE_DBLINK_NAME = OC_LOOPBACK_LINK
--   DEFINE ORACODE_DBLINK_USER = remote_user
--   DEFINE ORACODE_DBLINK_PASSWORD = remote_password
--   DEFINE ORACODE_DBLINK_CONNECT = localhost:1521/XE
--   @tests/fixtures/oracle/optional_db_link_template.sql

SET VERIFY OFF
WHENEVER SQLERROR EXIT SQL.SQLCODE

BEGIN
  EXECUTE IMMEDIATE 'DROP DATABASE LINK &&ORACODE_DBLINK_NAME';
EXCEPTION WHEN OTHERS THEN IF SQLCODE != -2024 THEN RAISE; END IF;
END;
/

CREATE DATABASE LINK &&ORACODE_DBLINK_NAME
  CONNECT TO &&ORACODE_DBLINK_USER IDENTIFIED BY "&&ORACODE_DBLINK_PASSWORD"
  USING '&&ORACODE_DBLINK_CONNECT';

PROMPT Optional database link fixture loaded as &&ORACODE_DBLINK_NAME
UNDEFINE ORACODE_DBLINK_NAME
UNDEFINE ORACODE_DBLINK_USER
UNDEFINE ORACODE_DBLINK_PASSWORD
UNDEFINE ORACODE_DBLINK_CONNECT
